            }
            for row in page
        ]
        next_cursor = (
            f"{cut}:{page[-1]['proposal_seq']}" if has_next else None
        )
        return {"proposals": proposals, "nextCursor": next_cursor}

    status, error, payload = self._read_snapshot_get(
