# ---- 只读全库审计检查点 ----

def _create_audit_checkpoint(self) -> None:
    idempotency_key = self.headers.get("Idempotency-Key")
    if (
        idempotency_key is None
        or IDEMPOTENCY_KEY_PATTERN.fullmatch(idempotency_key) is None
    ):
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    # 审计创建不接受任何查询参数：参数校验先于体校验。
    if parse_qsl(urlsplit(self.path).query, keep_blank_values=True):
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    # 正文必须恰为空对象（且不得含重复键）。
    raw_body = self._read_raw_body()
    valid_body = False
    if raw_body is not None:
        parsed = self._read_json_object(raw_body)
        valid_body = parsed is not None and not parsed
    if not valid_body:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    # 仅支持单一 SLA-Auth：缺失、重复、结构非法或携带代理头均为非法请求。
    if self.headers.get_all(SLA_DELEGATION_HEADER):
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    auth = self._parse_sla_auth()
    if auth is None:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    body_digest = hashlib.sha256(raw_body).hexdigest()
    status, payload = self._apply_audit_checkpoint(
        idempotency_key, auth, body_digest
    )
    self._json(status, payload)

@staticmethod
def _audit_difference(
    account_id: str,
    difference_type: str,
    entry_seq: int | None,
    reference_seq: int | None,
    expected: Any,
    actual: Any,
) -> dict[str, Any]:
    return {
        "accountId": account_id,
        "type": difference_type,
        "entrySeq": entry_seq,
        "referenceSeq": reference_seq,
        "expected": expected,
        "actual": actual,
    }

def _build_audit_document(
    self, database: Any, entry_seq_bound: int
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    # 在写事务内冻结：账本上界、存储余额、open 冻结、升级托管与仲裁结果。
    differences: list[dict[str, Any]] = []

    def add(
        account_id: str,
        difference_type: str,
        entry_seq: int | None = None,
        reference_seq: int | None = None,
        expected: Any = None,
        actual: Any = None,
    ) -> None:
        differences.append(
            self._audit_difference(
                account_id,
                difference_type,
                entry_seq,
                reference_seq,
                expected,
                actual,
            )
        )

    # 业务表全量载入（均为上界内已提交状态；写锁保证无并发改动）。
    deposits = {
        row["deposit_seq"]: row
        for row in database.execute(
            "SELECT deposit_seq, machine_id, amount_micros, reference"
            " FROM fund_deposits"
        ).fetchall()
    }
    settlements = {
        row["settlement_seq"]: row
        for row in database.execute(
            "SELECT settlement_seq, sla_id, evaluation_seq, result,"
            " amount_micros, payer_id, payee_id FROM settlements"
        ).fetchall()
    }
    evaluations = {
        row["evaluation_seq"]: row
        for row in database.execute(
            "SELECT evaluation_seq, sla_id"
            " FROM sla_evaluation_idempotency_records"
        ).fetchall()
    }
    disputes_by_id: dict[str, Any] = {}
    disputes_by_settlement: dict[int, Any] = {}
    for row in database.execute(
        "SELECT id, settlement_seq, claimant_id, payer_id, payee_id,"
        " amount_micros, state FROM disputes"
    ).fetchall():
        disputes_by_id[row["id"]] = row
        disputes_by_settlement[row["settlement_seq"]] = row
    escalations = {
        row["escalation_seq"]: row
        for row in database.execute(
            "SELECT escalation_seq, dispute_id, amount_micros"
            " FROM dispute_escalations"
        ).fetchall()
    }
    arbitrations = {
        row["arbitration_seq"]: row
        for row in database.execute(
            "SELECT arbitration_seq, escalation_seq, dispute_id,"
            " arbitrator_id, decision, amount_micros"
            " FROM dispute_arbitrations"
        ).fetchall()
    }

    entries = [
        dict(row)
        for row in database.execute(
            "SELECT entry_seq, kind, reference_seq, account_id,"
            " delta_micros, balance_after_micros"
            " FROM ledger_entries WHERE entry_seq <= ?"
            " ORDER BY entry_seq ASC",
            (entry_seq_bound,),
        ).fetchall()
    ]

    # 逐账户重放：累计值、每步余额，并在最后与存储余额核对。
    stored_balances = {
        row["account_id"]: row["balance_micros"]
        for row in database.execute(
            "SELECT account_id, balance_micros FROM ledger_accounts"
        ).fetchall()
    }
    account_ids = set(stored_balances)
    account_ids.add(CLEARING_ACCOUNT_ID)
    account_ids.update(entry["account_id"] for entry in entries)

    frozen_by_account: dict[str, int] = {}
    for row in disputes_by_id.values():
        if row["state"] == "open":
            frozen_by_account[row["payee_id"]] = (
                frozen_by_account.get(row["payee_id"], 0)
                + row["amount_micros"]
            )

    entries_by_account: dict[str, list[dict[str, Any]]] = {
        account_id: [] for account_id in account_ids
    }
    for entry in entries:
        entries_by_account.setdefault(entry["account_id"], []).append(entry)

    accounts: list[dict[str, Any]] = []
    for account_id in sorted(account_ids):
        running = 0
        count = 0
        for entry in entries_by_account.get(account_id, []):
            expected_balance = running + entry["delta_micros"]
            if entry["balance_after_micros"] != expected_balance:
                add(
                    account_id,
                    "step_balance_mismatch",
                    entry["entry_seq"],
                    entry["reference_seq"],
                    expected_balance,
                    entry["balance_after_micros"],
                )
            running = expected_balance
            count += 1
        stored = stored_balances.get(account_id, 0)
        if running != stored:
            add(
                account_id,
                "balance_mismatch",
                None,
                None,
                running,
                stored,
            )
        frozen = frozen_by_account.get(account_id, 0)
        accounts.append(
            {
                "accountId": account_id,
                "storedBalance": stored,
                "replayedBalance": running,
                "frozen": frozen,
                "availableBalance": max(0, stored - frozen),
                "entryCount": count,
            }
        )

    # 逐笔核对方向、业务引用、SLA 与评估归属；并按 (kind, referenceSeq)
    # 核对资金分录成对守恒。
    pairs: dict[tuple[str, int], list[dict[str, Any]]] = {}
    for entry in entries:
        pairs.setdefault(
            (entry["kind"], entry["reference_seq"]), []
        ).append(entry)
        account_id = entry["account_id"]
        kind = entry["kind"]
        reference_seq = entry["reference_seq"]
        delta = entry["delta_micros"]
        entry_seq = entry["entry_seq"]

        if kind == "deposit":
            deposit = deposits.get(reference_seq)
            if deposit is None:
                add(account_id, "entry_reference", entry_seq, reference_seq)
                continue
            if account_id == deposit["machine_id"]:
                expected_delta = deposit["amount_micros"]
            elif account_id == CLEARING_ACCOUNT_ID:
                expected_delta = -deposit["amount_micros"]
            else:
                add(account_id, "entry_direction", entry_seq, reference_seq)
                continue
            if delta != expected_delta:
                add(
                    account_id,
                    "entry_direction",
                    entry_seq,
                    reference_seq,
                    expected_delta,
                    delta,
                )
            continue

        if kind == "settlement":
            settlement = settlements.get(reference_seq)
            if settlement is None:
                add(account_id, "entry_reference", entry_seq, reference_seq)
                continue
            expected_account = None
            expected_delta = None
            if account_id == settlement["payer_id"]:
                expected_account, expected_delta = account_id, -settlement[
                    "amount_micros"
                ]
            elif account_id == settlement["payee_id"]:
                expected_account, expected_delta = account_id, settlement[
                    "amount_micros"
                ]
            if expected_account is None or delta != expected_delta:
                add(
                    account_id,
                    "entry_direction",
                    entry_seq,
                    reference_seq,
                    settlement["amount_micros"],
                    delta,
                )
            evaluation = evaluations.get(settlement["evaluation_seq"])
            if (
                evaluation is None
                or evaluation["sla_id"] != settlement["sla_id"]
            ):
                add(
                    account_id,
                    "entry_attribution",
                    entry_seq,
                    reference_seq,
                    settlement["sla_id"],
                    None if evaluation is None else evaluation["sla_id"],
                )
            continue

        if kind == "dispute_refund":
            settlement = settlements.get(reference_seq)
            dispute = disputes_by_settlement.get(reference_seq)
            if settlement is None or dispute is None:
                add(account_id, "entry_reference", entry_seq, reference_seq)
                continue
            if dispute["state"] != "refunded":
                add(account_id, "entry_reference", entry_seq, reference_seq)
            if account_id == dispute["payer_id"]:
                expected_delta = settlement["amount_micros"]
            elif account_id == dispute["payee_id"]:
                expected_delta = -settlement["amount_micros"]
            else:
                add(account_id, "entry_direction", entry_seq, reference_seq)
                continue
            if delta != expected_delta or delta == 0 and False:
                add(
                    account_id,
                    "entry_direction",
                    entry_seq,
                    reference_seq,
                    expected_delta,
                    delta,
                )
            evaluation = evaluations.get(settlement["evaluation_seq"])
            if (
                evaluation is None
                or evaluation["sla_id"] != settlement["sla_id"]
            ):
                add(
                    account_id,
                    "entry_attribution",
                    entry_seq,
                    reference_seq,
                    settlement["sla_id"],
                    None if evaluation is None else evaluation["sla_id"],
                )
            continue

        if kind == "dispute_escalation":
            escalation = escalations.get(reference_seq)
            if escalation is None:
                add(account_id, "entry_reference", entry_seq, reference_seq)
                continue
            dispute = disputes_by_id.get(escalation["dispute_id"])
            if dispute is None:
                add(account_id, "entry_reference", entry_seq, reference_seq)
                continue
            settlement = settlements.get(dispute["settlement_seq"])
            if settlement is None:
                add(account_id, "entry_attribution", entry_seq, reference_seq)
            if account_id == dispute["payee_id"]:
                expected_delta = -escalation["amount_micros"]
            elif account_id == CLEARING_ACCOUNT_ID:
                expected_delta = escalation["amount_micros"]
            else:
                add(account_id, "entry_direction", entry_seq, reference_seq)
                continue
            if delta != expected_delta:
                add(
                    account_id,
                    "entry_direction",
                    entry_seq,
                    reference_seq,
                    expected_delta,
                    delta,
                )
            continue

        if kind == "dispute_arbitration":
            arbitration = arbitrations.get(reference_seq)
            if arbitration is None:
                add(account_id, "entry_reference", entry_seq, reference_seq)
                continue
            dispute = disputes_by_id.get(arbitration["dispute_id"])
            if dispute is None:
                add(account_id, "entry_reference", entry_seq, reference_seq)
                continue
            expected_state = (
                "released"
                if arbitration["decision"] == "release"
                else "refunded"
            )
            if dispute["state"] != expected_state:
                add(account_id, "entry_reference", entry_seq, reference_seq)
            recipient_id = (
                dispute["payee_id"]
                if arbitration["decision"] == "release"
                else dispute["payer_id"]
            )
            if account_id == CLEARING_ACCOUNT_ID:
                expected_delta = -arbitration["amount_micros"]
            elif account_id == recipient_id:
                expected_delta = arbitration["amount_micros"]
            else:
                add(account_id, "entry_direction", entry_seq, reference_seq)
                continue
            if delta != expected_delta:
                add(
                    account_id,
                    "entry_direction",
                    entry_seq,
                    reference_seq,
                    expected_delta,
                    delta,
                )
            settlement = settlements.get(dispute["settlement_seq"])
            if settlement is None:
                add(account_id, "entry_attribution", entry_seq, reference_seq)
            continue

        # 未知分录种类：业务引用无法核对。
        add(account_id, "entry_reference", entry_seq, reference_seq)

    for (kind, reference_seq), pair in pairs.items():
        if len(pair) != 2:
            for entry in pair:
                add(
                    entry["account_id"],
                    "entry_unpaired",
                    entry["entry_seq"],
                    reference_seq,
                )
            continue
        total = sum(entry["delta_micros"] for entry in pair)
        if total != 0:
            anchor = pair[0]
            add(
                anchor["account_id"],
                "entry_pair_amount",
                anchor["entry_seq"],
                reference_seq,
                0,
                total,
            )

    # 争议冻结与状态快照（按争议标识稳定排序）。
    disputes_document = [
        {
            "disputeId": row["id"],
            "settlementSeq": row["settlement_seq"],
            "payerId": row["payer_id"],
            "payeeId": row["payee_id"],
            "amount": row["amount_micros"],
            "state": row["state"],
        }
        for row in sorted(disputes_by_id.values(), key=lambda item: item["id"])
    ]

    # 升级托管：未仲裁（争议当前仍为 escalated）的升级金额计为清算负债，
    # 与升级记录及外部清算余额交叉核对。
    liability = 0
    recorded_escrow = 0
    for dispute in disputes_by_id.values():
        if dispute["state"] == "escalated":
            liability += dispute["amount_micros"]
    escalations_document = []
    for escalation_seq in sorted(escalations):
        escalation = escalations[escalation_seq]
        dispute = disputes_by_id.get(escalation["dispute_id"])
        arbitrated = any(
            arbitration["dispute_id"] == escalation["dispute_id"]
            for arbitration in arbitrations.values()
        )
        if dispute is not None and dispute["state"] == "escalated":
            recorded_escrow += escalation["amount_micros"]
            if escalation["amount_micros"] != dispute["amount_micros"]:
                add(
                    CLEARING_ACCOUNT_ID,
                    "escrow_amount_mismatch",
                    None,
                    escalation_seq,
                    dispute["amount_micros"],
                    escalation["amount_micros"],
                )
        if dispute is None:
            add(
                CLEARING_ACCOUNT_ID,
                "escalation_dispute_missing",
                None,
                escalation_seq,
            )
        escalations_document.append(
            {
                "escalationSeq": escalation_seq,
                "disputeId": escalation["dispute_id"],
                "amount": escalation["amount_micros"],
                "arbitrated": arbitrated,
            }
        )
    if liability != recorded_escrow:
        add(
            CLEARING_ACCOUNT_ID,
            "escrow_record_mismatch",
            None,
            None,
            liability,
            recorded_escrow,
        )

    # 仲裁结果冻结，并核对仲裁与升级的归属。
    arbitrations_document = []
    for arbitration_seq in sorted(arbitrations):
        arbitration = arbitrations[arbitration_seq]
        escalation = escalations.get(arbitration["escalation_seq"])
        if (
            escalation is None
            or escalation["dispute_id"] != arbitration["dispute_id"]
        ):
            add(
                CLEARING_ACCOUNT_ID,
                "arbitration_escalation_mismatch",
                None,
                arbitration_seq,
            )
        arbitrations_document.append(
            {
                "arbitrationSeq": arbitration_seq,
                "escalationSeq": arbitration["escalation_seq"],
                "disputeId": arbitration["dispute_id"],
                "arbitratorId": arbitration["arbitrator_id"],
                "decision": arbitration["decision"],
                "amount": arbitration["amount_micros"],
            }
        )

    # 外部清算余额 = 升级托管 − 累计入金（入金为清算负债的反向分录，
    # 结算、退款仅在机器账户间转移）。
    deposit_total = sum(deposit["amount_micros"] for deposit in deposits.values())
    clearing_balance = stored_balances.get(CLEARING_ACCOUNT_ID, 0)
    expected_clearing = recorded_escrow - deposit_total
    if clearing_balance != expected_clearing:
        add(
            CLEARING_ACCOUNT_ID,
            "clearing_balance_mismatch",
            None,
            None,
            expected_clearing,
            clearing_balance,
        )
    clearing_document = {
        "accountId": CLEARING_ACCOUNT_ID,
        "storedBalance": clearing_balance,
        "depositTotal": deposit_total,
        "escrowLiability": recorded_escrow,
        "expectedBalance": expected_clearing,
    }

    # 差异项按账户、类型、引用序号稳定排序（空序号排在最前）。
    differences = sorted(
        (dict(item) for item in {tuple(sorted(item.items())) for item in differences}),
        key=lambda item: (
            item["accountId"],
            item["type"],
            item["referenceSeq"] is not None,
            item["referenceSeq"] if item["referenceSeq"] is not None else 0,
            item["entrySeq"] is not None,
            item["entrySeq"] if item["entrySeq"] is not None else 0,
        ),
    )

    document = {
        "entrySeqBound": entry_seq_bound,
        "consistent": not differences,
        "accounts": accounts,
        "disputes": disputes_document,
        "escalations": escalations_document,
        "arbitrations": arbitrations_document,
        "clearing": clearing_document,
        "differences": differences,
    }
    return document, differences

def _apply_audit_checkpoint(
    self,
    idempotency_key: str,
    auth: SlaAuth,
    body_digest: str,
) -> tuple[HTTPStatus, dict[str, Any]]:
    request_json = "{}"
    standard_path = "/v1/audit-checkpoints"
    with closing(connect(self.server.database_path)) as database:
        database.execute("BEGIN IMMEDIATE")
        try:
            # 幂等判定先于授权与认证：同键更换正文或认证五段均冲突。
            record = database.execute(
                "SELECT request_json, status, response_json,"
                " auth_machine_id, auth_key_version, auth_request_time_ms,"
                " auth_nonce, auth_signature"
                " FROM audit_checkpoint_idempotency_records WHERE key = ?",
                (idempotency_key,),
            ).fetchone()
            if record is not None:
                database.execute("ROLLBACK")
                if record["request_json"] == request_json and (
                    record["auth_machine_id"] is not None
                    and self._auth_record_matches(record, auth)
                ):
                    return HTTPStatus(record["status"]), json.loads(
                        record["response_json"]
                    )
                return HTTPStatus.CONFLICT, {"error": "conflict"}
            # 认证机器须为启动时配置的审计机器；未配置一律 403。
            if auth.machine_id not in self.server.auditors:
                database.execute("ROLLBACK")
                return HTTPStatus.FORBIDDEN, {"error": "forbidden"}
            try:
                self._verify_request_principal(
                    database, auth, standard_path, body_digest
                )
                self._check_request_nonce(database, auth)
            except AuthRejected as rejected:
                database.execute("ROLLBACK")
                return rejected.status, {"error": rejected.error}
            # 冻结账本上界：取写锁后全库最大分录序号（空库为 0）。
            bound_record = database.execute(
                "SELECT COALESCE(MAX(entry_seq), 0) AS bound"
                " FROM ledger_entries"
            ).fetchone()
            entry_seq_bound = bound_record["bound"]
            document, differences = self._build_audit_document(
                database, entry_seq_bound
            )
            document_bytes = json.dumps(
                document, ensure_ascii=False, separators=(",", ":")
            ).encode("utf-8")
            digest = hashlib.sha256(document_bytes).hexdigest()
            # 全库唯一持久递增检查点序号：取最大序号 + 1（空表 1）。
            checkpoint_seq = database.execute(
                "SELECT COALESCE(MAX(checkpoint_seq), 0) + 1 AS next_seq"
                " FROM audit_checkpoints"
            ).fetchone()["next_seq"]
            created_at_ms = int(datetime.now(UTC).timestamp() * 1000)
            # 即使存在差异也保存不一致结论；审计不修正任何业务数据。
            payload = {
                "checkpointSeq": checkpoint_seq,
                "entrySeqBound": entry_seq_bound,
                "digest": digest,
                "createdBy": auth.machine_id,
                "createdAt": created_at_ms,
                "consistent": document["consistent"],
                "accounts": document["accounts"],
                "disputes": document["disputes"],
                "escalations": document["escalations"],
                "arbitrations": document["arbitrations"],
                "clearing": document["clearing"],
                "differences": document["differences"],
            }
            response_json = json.dumps(payload, separators=(",", ":"))
            database.execute(
                "INSERT INTO audit_checkpoints"
                "(checkpoint_seq, entry_seq_bound, digest, created_by,"
                " created_at_ms, document_json, response_json)"
                " VALUES (?, ?, ?, ?, ?, ?, ?)",
                (
                    checkpoint_seq,
                    entry_seq_bound,
                    digest,
                    auth.machine_id,
                    created_at_ms,
                    document_bytes.decode("utf-8"),
                    response_json,
                ),
            )
            database.execute(
                "INSERT INTO audit_checkpoint_idempotency_records"
                "(key, request_json, status, response_json,"
                " auth_machine_id, auth_key_version, auth_request_time_ms,"
                " auth_nonce, auth_signature)"
                " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    idempotency_key,
                    request_json,
                    int(HTTPStatus.CREATED),
                    response_json,
                    auth.machine_id,
                    auth.key_version,
                    auth.request_time_ms,
                    auth.nonce,
                    auth.signature,
                ),
            )
            # 检查点、幂等结果与随机数同一事务原子持久化；
            # 任何失败路径都不到达此处，不消费随机数、不推进序号。
            self._consume_request_nonce(database, auth)
            database.execute("COMMIT")
            _ = differences
            return HTTPStatus.CREATED, payload
        except BaseException:
            database.execute("ROLLBACK")
            raise

def _get_audit_checkpoints(self, query: str) -> None:
    # 集合分页沿用评估历史的 limit 与 cursor=cut:lastSeq。
    parsed = self._parse_evaluation_query(
        query, AUDIT_CHECKPOINTS_QUERY_PARAMS
    )
    if parsed is None:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    limit, cursor = parsed
    if self.headers.get_all(SLA_DELEGATION_HEADER):
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    auth = self._parse_sla_auth()
    if auth is None:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    body_digest = hashlib.sha256(b"").hexdigest()
    standard_path = "/v1/audit-checkpoints"
    with closing(connect(self.server.database_path)) as database:
        database.execute("BEGIN IMMEDIATE")
        try:
            if auth.machine_id not in self.server.auditors:
                database.execute("ROLLBACK")
                self._json(HTTPStatus.FORBIDDEN, {"error": "forbidden"})
                return
            try:
                self._verify_request_principal(
                    database, auth, standard_path, body_digest
                )
                self._check_request_nonce(database, auth)
            except AuthRejected as rejected:
                database.execute("ROLLBACK")
                self._json(rejected.status, {"error": rejected.error})
                return
            max_record = database.execute(
                "SELECT COALESCE(MAX(checkpoint_seq), 0) AS current_max"
                " FROM audit_checkpoints"
            ).fetchone()
            current_max = max_record["current_max"]
            if cursor is None:
                cut = current_max
                last_seq = 0
            else:
                cut, last_seq = cursor
                if cut > current_max:
                    database.execute("ROLLBACK")
                    self._json(
                        HTTPStatus.BAD_REQUEST, {"error": "invalid_request"}
                    )
                    return
                anchor = database.execute(
                    "SELECT 1 FROM audit_checkpoints"
                    " WHERE checkpoint_seq = ? AND checkpoint_seq <= ?",
                    (last_seq, cut),
                ).fetchone()
                if anchor is None:
                    database.execute("ROLLBACK")
                    self._json(
                        HTTPStatus.BAD_REQUEST, {"error": "invalid_request"}
                    )
                    return
            rows = database.execute(
                "SELECT checkpoint_seq, entry_seq_bound, digest, created_by,"
                " created_at_ms FROM audit_checkpoints"
                " WHERE checkpoint_seq <= ? AND checkpoint_seq > ?"
                " ORDER BY checkpoint_seq ASC"
                " LIMIT ?",
                (cut, last_seq, limit + 1),
            ).fetchall()
            has_next = len(rows) > limit
            page = rows[:limit]
            checkpoints = [
                {
                    "checkpointSeq": row["checkpoint_seq"],
                    "entrySeqBound": row["entry_seq_bound"],
                    "digest": row["digest"],
                    "createdBy": row["created_by"],
                    "createdAt": row["created_at_ms"],
                }
                for row in page
            ]
            next_cursor = (
                f"{cut}:{page[-1]['checkpoint_seq']}" if has_next else None
            )
            self._consume_request_nonce(database, auth)
            database.execute("COMMIT")
        except BaseException:
            database.execute("ROLLBACK")
            raise
    self._json(
        HTTPStatus.OK,
        {"checkpoints": checkpoints, "nextCursor": next_cursor},
    )

def _get_audit_checkpoint(self, seq_text: str, query: str) -> None:
    # 单笔读取不接受任何查询参数：参数校验先于认证结构。
    if parse_qsl(query, keep_blank_values=True):
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    # 序号须为无前导零十进制正整数；非法按不存在处理。
    checkpoint_seq: int | None = None
    if DECIMAL_PATTERN.fullmatch(seq_text) is not None:
        value = int(seq_text)
        if 1 <= value <= INT64_MAX:
            checkpoint_seq = value
    if self.headers.get_all(SLA_DELEGATION_HEADER):
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    auth = self._parse_sla_auth()
    if auth is None:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    body_digest = hashlib.sha256(b"").hexdigest()
    standard_path = f"/v1/audit-checkpoints/{seq_text}"
    with closing(connect(self.server.database_path)) as database:
        database.execute("BEGIN IMMEDIATE")
        try:
            if auth.machine_id not in self.server.auditors:
                database.execute("ROLLBACK")
                self._json(HTTPStatus.FORBIDDEN, {"error": "forbidden"})
                return
            try:
                self._verify_request_principal(
                    database, auth, standard_path, body_digest
                )
                self._check_request_nonce(database, auth)
            except AuthRejected as rejected:
                database.execute("ROLLBACK")
                self._json(rejected.status, {"error": rejected.error})
                return
            record = None
            if checkpoint_seq is not None:
                record = database.execute(
                    "SELECT response_json FROM audit_checkpoints"
                    " WHERE checkpoint_seq = ?",
                    (checkpoint_seq,),
                ).fetchone()
            if record is None:
                database.execute("ROLLBACK")
                self._json(HTTPStatus.NOT_FOUND, {"error": "not_found"})
                return
            payload = json.loads(record["response_json"])
            # 仅成功读取才在同一事务消费随机数。
            self._consume_request_nonce(database, auth)
            database.execute("COMMIT")
        except BaseException:
            database.execute("ROLLBACK")
            raise
    self._json(HTTPStatus.OK, payload)

def log_message(self, format: str, *args: object) -> None:
    return

